package org.jlinalg.cli;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.AccessDeniedException;
import java.nio.file.Files;
import java.nio.file.LinkOption;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import org.jlinalg.genetics.BigWigWriter;

/** Public captured conversion, final admission and portable complete native verification. */
final class BigWigWorkflow {
    private BigWigWorkflow() { }
    static final String ACTION="Required action: read WARNINGS.md, FAILURE.json and its named stage when present, request.json, INPUT-AUDIT.json, OUTPUT-AUDIT.json, VALUE-LEDGER.tsv and REFERENCE-LEDGER.tsv. Require overall COMPLETED.json, no INCOMPLETE.json/FAILURE.json, and successful bigwig-tools --verify before downstream use. SKIP3 means required permitted input/output access is forbidden: supply the named permitted resource or skip this dependent conversion. No installation is needed or attempted. FAIL2 means input, precision, integrity, capacity, I/O, cancellation or finalization failure: no result admitted. Preserve the whole attempt/partial track, correct the cause and use NEW paths. Never silently clip, normalize, average overlaps, alias chromosome identities or fill missing signal with zeros. Declared file/record capacities are not a JVM heap guarantee. Hashes establish integrity, not authenticity or biological accuracy. Cell Ranger remains excluded.";
    record Result(Path root,BigWigRequest.Spec request,BigWigWriter.Report report) { }
    static Result start(BigWigRequest.Spec s,Path root,Runnable check)throws IOException {
        boolean fresh=false;String stage="CREATE_ATTEMPT";
        try{
            BigWigFiles.create(root);fresh=true;BigWigFiles.json(root.resolve("INCOMPLETE.json"),Map.of("status","NATIVE_CONVERSION_NOT_COMMITTED","conversion_admitted",false));Files.createDirectory(root.resolve("inputs"));BigWigFiles.json(root.resolve("request.json"),s.document());Files.writeString(root.resolve("WARNINGS.md"),"# INCOMPLETE — NO RESULT ADMITTED\n\n"+ACTION+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);
            stage="CAPTURE_COMPLETE_INPUTS";Path signal=Path.of(s.input()),sizes=Path.of(s.sizes());var source=NextflowFiles.pin(signal,s.inputBytes(),check);var reference=NextflowFiles.pin(sizes,s.inputBytes(),check);long inputBytes=Math.addExact(source.bytes(),reference.bytes());require(inputBytes<=s.inputBytes(),"Combined original signal/reference bytes exceed input-bytes");require(inputBytes+BigWigFiles.FINAL_RESERVE<s.workspaceBytes(),"Workspace cannot retain complete inputs and final metadata reserve");BigWigFiles.copy(signal,root.resolve(s.member()),source,check);BigWigFiles.copy(sizes,root.resolve("inputs/reference.sizes"),reference,check);BigWigFiles.json(root.resolve("source-pins.json"),Map.of("signal",BigWigFiles.pin(source),"reference",BigWigFiles.pin(reference),"combined_source_bytes",inputBytes,"unchanged_raw_inputs",true));
            stage="PARSE_COMPLETE_INPUTS_AND_LEDGERS";long ledgerCapacity=s.workspaceBytes()-inputBytes-BigWigFiles.FINAL_RESERVE;var data=BigWigText.read(root,s,false,ledgerCapacity,check);BigWigFiles.json(root.resolve("INPUT-AUDIT.json"),data.audit());long prepared=total(BigWigFiles.inventory(root,s,check));require(prepared+s.outputBytes()+BigWigFiles.FINAL_RESERVE<=s.workspaceBytes(),"Workspace must cover complete prepared evidence, requested output-bytes and16MiB final metadata reserve; review workspace/output capacities explicitly");
            stage="WRITE_NATIVE_BIGWIG";var report=BigWigWriter.write(root.resolve("track.bw"),data.reference(),data.rows(),s.options(),check);stage="VERIFY_COMPLETE_NATIVE_OUTPUT";require(report.equals(BigWigWriter.verify(root.resolve("track.bw"),data.reference(),data.rows(),s.options(),check)),"Complete native output replay differs");BigWigFiles.json(root.resolve("OUTPUT-AUDIT.json"),output(root,s,report,check));Files.writeString(root.resolve("WARNINGS.md"),warnings(s,data,report),StandardCharsets.UTF_8,StandardOpenOption.TRUNCATE_EXISTING);
            stage="FINALIZE_CAPTURED_CONVERSION";require(source.equals(NextflowFiles.pin(signal,s.inputBytes(),check))&&reference.equals(NextflowFiles.pin(sizes,s.inputBytes(),check)),"Original input/reference changed during conversion");var files=new TreeMap<>(BigWigFiles.inventory(root,s,check));require(files.remove("INCOMPLETE.json")!=null,"Missing private incomplete guard");BigWigFiles.json(root.resolve("manifest.json"),Map.of("schema_version",1,"profile",BigWigRequest.PROFILE,"status","COMPLETE_NATIVE_BIGWIG_CAPTURED_CONTRACT","files",files,"conversion_admitted",true,"biological_accuracy_certified",false));BigWigFiles.json(root.resolve("COMPLETED.json"),Map.of("schema_version",1,"status","COMPLETE_NATIVE_BIGWIG_CONVERSION","manifest",BigWigFiles.pin(NextflowFiles.pin(root.resolve("manifest.json"),2097152,check)),"conversion_admitted",true));
            Result result=verify(root,true,check);require(source.equals(NextflowFiles.pin(signal,s.inputBytes(),check))&&reference.equals(NextflowFiles.pin(sizes,s.inputBytes(),check)),"Original sources changed before final commit");check.run();Files.delete(root.resolve("INCOMPLETE.json"));return result;
        }catch(IOException|RuntimeException|Error failure){if(fresh)failure(root,stage,failure);throw failure;}
    }
    static Result verify(Path root,Runnable check)throws IOException {return verify(root,false,check);}
    private static Result verify(Path root,boolean precommit,Runnable check)throws IOException {
        NextflowFiles.directory(root);check.run();require(!Files.exists(root.resolve("FAILURE.json"),LinkOption.NOFOLLOW_LINKS),"Native conversion retains a failure/skip");require(precommit==Files.exists(root.resolve("INCOMPLETE.json"),LinkOption.NOFOLLOW_LINKS),"Native conversion is incomplete; a file/component marker is insufficient");if(precommit){var guard=BigWigFiles.json(root.resolve("INCOMPLETE.json"),65536);NextflowFiles.keys(guard,"status","conversion_admitted");require("NATIVE_CONVERSION_NOT_COMMITTED".equals(guard.get("status"))&&Boolean.FALSE.equals(guard.get("conversion_admitted")),"Private incomplete guard differs");}
        var completion=BigWigFiles.json(root.resolve("COMPLETED.json"),65536);NextflowFiles.keys(completion,"schema_version","status","manifest","conversion_admitted");NextflowFiles.integer(completion.get("schema_version"),1,1);require("COMPLETE_NATIVE_BIGWIG_CONVERSION".equals(completion.get("status"))&&Boolean.TRUE.equals(completion.get("conversion_admitted")),"Overall native conversion completion is absent/unadmitted");var manifestPin=NextflowFiles.pin(root.resolve("manifest.json"),2097152,check);require(manifestPin.equals(NextflowFiles.fingerprint(completion.get("manifest"),2097152)),"Native manifest hash differs");var manifest=BigWigFiles.json(root.resolve("manifest.json"),2097152);NextflowFiles.keys(manifest,"schema_version","profile","status","files","conversion_admitted","biological_accuracy_certified");NextflowFiles.integer(manifest.get("schema_version"),1,1);require(BigWigRequest.PROFILE.equals(manifest.get("profile"))&&"COMPLETE_NATIVE_BIGWIG_CAPTURED_CONTRACT".equals(manifest.get("status"))&&Boolean.TRUE.equals(manifest.get("conversion_admitted"))&&Boolean.FALSE.equals(manifest.get("biological_accuracy_certified")),"Native captured profile/status differs");var s=BigWigRequest.captured(BigWigFiles.json(root.resolve("request.json"),2097152));inventory(root,s,manifest.get("files"),precommit,check);
        var sources=BigWigFiles.json(root.resolve("source-pins.json"),65536);NextflowFiles.keys(sources,"signal","reference","combined_source_bytes","unchanged_raw_inputs");var signal=NextflowFiles.pin(root.resolve(s.member()),s.inputBytes(),check);var reference=NextflowFiles.pin(root.resolve("inputs/reference.sizes"),s.inputBytes(),check);long bytes=Math.addExact(signal.bytes(),reference.bytes());require(bytes<=s.inputBytes()&&bytes==NextflowFiles.integer(sources.get("combined_source_bytes"),0,s.inputBytes())&&signal.equals(NextflowFiles.fingerprint(sources.get("signal"),s.inputBytes()))&&reference.equals(NextflowFiles.fingerprint(sources.get("reference"),s.inputBytes()))&&Boolean.TRUE.equals(sources.get("unchanged_raw_inputs")),"Complete captured input/reference hashes differ");
        var data=BigWigText.read(root,s,true,s.workspaceBytes()-bytes-BigWigFiles.FINAL_RESERVE,check);require(same(data.audit(),BigWigFiles.json(root.resolve("INPUT-AUDIT.json"),2097152)),"Complete source/default/precision audit differs");var report=BigWigWriter.verify(root.resolve("track.bw"),data.reference(),data.rows(),s.options(),check);require(same(output(root,s,report,check),BigWigFiles.json(root.resolve("OUTPUT-AUDIT.json"),2097152)),"Complete native output/ledger audit differs");require(NextflowFiles.utf8(NextflowFiles.bytes(root.resolve("WARNINGS.md"),2097152)).equals(warnings(s,data,report)),"Native precision/reference/compatibility warnings or recovery instructions differ");inventory(root,s,manifest.get("files"),precommit,check);require(manifestPin.equals(NextflowFiles.pin(root.resolve("manifest.json"),2097152,check)),"Native manifest changed during portable verification");return new Result(root,s,report);
    }
    private static void inventory(Path root,BigWigRequest.Spec s,Object expected,boolean precommit,Runnable check)throws IOException {var files=new TreeMap<>(BigWigFiles.inventory(root,s,check));var required=new HashSetBuilder().base(s.member());if(precommit)required.add("INCOMPLETE.json");require(files.keySet().equals(required.values),"Native bundle family has missing/unknown files or directories");files.remove("manifest.json");files.remove("COMPLETED.json");if(precommit)files.remove("INCOMPLETE.json");require(same(BigWigFiles.portable(files),BigWigFiles.portable(expected)),"Complete native bundle bytes, node kinds or namespace differ");}
    private static final class HashSetBuilder {final java.util.Set<String> values=new java.util.HashSet<>();HashSetBuilder base(String input){values.addAll(Set.of(".","inputs",input,"inputs/reference.sizes","request.json","source-pins.json","INPUT-AUDIT.json","VALUE-LEDGER.tsv","REFERENCE-LEDGER.tsv","track.bw","OUTPUT-AUDIT.json","WARNINGS.md","manifest.json","COMPLETED.json"));return this;}void add(String name){values.add(name);}}
    static Map<String,Object> output(Path root,BigWigRequest.Spec s,BigWigWriter.Report r,Runnable check)throws IOException {var result=new LinkedHashMap<String,Object>();result.put("profile",BigWigRequest.PROFILE);result.put("engine","native-java");result.put("complete_raw_intervals",r.records());result.put("raw_sections",r.sections());result.put("stored_chromosomes",r.dictionary().size());result.put("covered_bases",r.coveredBases());result.put("minimum_float32_hex",Float.toHexString((float)r.minimum()));result.put("maximum_float32_hex",Float.toHexString((float)r.maximum()));result.put("sum_float64_hex",Double.toHexString(r.sum()));result.put("sum_squares_float64_hex",Double.toHexString(r.sumSquares()));result.put("rounded_float64_values",r.roundedValues());result.put("float64_values_underflowed_in_float32",r.underflowedValues());result.put("maximum_raw_block_bytes",r.maximumRawBlock());result.put("track",BigWigFiles.pin(NextflowFiles.pin(root.resolve("track.bw"),s.outputBytes(),check)));result.put("value_ledger",BigWigFiles.pin(NextflowFiles.pin(root.resolve("VALUE-LEDGER.tsv"),s.workspaceBytes(),check)));result.put("reference_ledger",BigWigFiles.pin(NextflowFiles.pin(root.resolve("REFERENCE-LEDGER.tsv"),s.workspaceBytes(),check)));result.put("complete_native_raw_output_contract",true);result.put("zoom_levels",0);result.put("upstream_binary_or_summary_identity_claimed",false);result.put("biological_accuracy_certified",false);return result;}
    static String warnings(BigWigRequest.Spec s,BigWigText.Data data,BigWigWriter.Report report)throws IOException {
        var notes=new ArrayList<String>();notes.add("Native Java bigWig v4 conversion of complete unchanged supplied inputs. Declared build="+s.build()+"; units="+s.units()+". These labels do not authenticate an assembly or establish signal normalization. No chromosome aliasing, clipping, overlap averaging, record filtering or missing-base zero filling occurred.");notes.add("PRECISION POLICY="+s.precision()+". Input decimal tokens are interpreted as float64 and stored as float32. VALUE-LEDGER.tsv retains every token, exact hexadecimal float64/float32 value, float32 bits and underflow stage. Exact policy requires equality to the literal input decimal, including decimal information lost before float32 conversion.");
        long changed=number(data,"literal_decimal_values_changed_in_float32"),doubles=number(data,"literal_decimal_values_changed_in_float64"),under64=number(data,"literal_values_underflowed_in_float64"),under32=number(data,"float64_values_underflowed_in_float32");if(changed>0||under64>0||under32>0)notes.add("PRECISION LOSS: "+changed+" literal decimal values changed in float32; "+doubles+" already changed in float64; "+under64+" nonzero literals underflowed in float64; "+under32+" further values underflowed in float32. Review every disposition; printed/stored zero is not evidence of biological absence. Rounding was explicitly permitted.");
        notes.add("DICTIONARY POLICY="+s.dictionary()+". REFERENCE-LEDGER.tsv retains all "+data.reference().size()+" declared chromosomes, every original size token, stored/omitted disposition and binary chromosome ID. Native binary dictionary/data use unsigned UTF8 byte order; source files and input ordinals remain unchanged.");if(number(data,"omitted_unused_reference_chromosomes")>0)notes.add("OMITTED UNUSED CHROMOSOMES: "+number(data,"omitted_unused_reference_chromosomes")+" reference rows are omitted only by the explicit used policy. They are retained in raw sizes/reference ledger; omission is not biological absence.");if(report.records()==0)notes.add("EMPTY TRACK: no measured signal intervals are present. All-reference dictionary was explicitly requested; zero summary fields do not represent measured zero signal. The pinned original converter rejects an empty input; no original-converter equivalence is claimed.");if(number(data,"initial_track_or_browser_lines")>0)notes.add("SOURCE METADATA: "+number(data,"initial_track_or_browser_lines")+" initial track/browser lines are preserved raw and counted, but their display settings are not applied to signal or normalization.");
        notes.add("NATIVE SUMMARY ARITHMETIC: totals use stored float32 values with double products and compensated double sums. They differ from UCSC2.10 float arithmetic. Original finite raw signals can produce infinite original sums of squares; the pinned Cygwin pyBigWig0.3.26 header reader crashed on one such original file. Native summaries remain finite for this admitted bounded population. No original summary-bit or binary-layout identity is claimed.");notes.add("NO ZOOM APPROXIMATIONS: complete full-resolution chromosome/R-tree indexes and raw data are stored, with0 zoom levels. Large-range consumers may require more raw I/O; original zoom selection, approximate statistics and rendering performance are not reproduced.");if(number(data,"reference_lengths_above_signed31")>0||number(data,"signal_records_above_signed31")>0)notes.add("UNSIGNED32 COMPATIBILITY: this input includes lengths/coordinates above signed31. UCSC independently read unsigned native coordinates, while the pinned Cygwin pyBigWig0.3.26 reader returned a signed view and the original converter timed out on the boundary probe. Native coordinates remain unsigned32 and unmodified. Verify the intended downstream consumer before using these ranges.");
        notes.add("RESOURCE CAPACITIES: complete input/decoded/record/line/output/workspace limits are retained in request.json. The requested maximum output and16MiB final metadata reserve must fit alongside complete prepared evidence; capacities are never silently lowered. These limits do not guarantee Java heap availability. Preserve failures and explicitly review capacities before a NEW attempt.");notes.add("PORTABLE VERIFICATION: only captured complete inputs and outputs are opened; recorded producer paths remain opaque provenance text. Copied filesystem modes are not producer-permission certificates. Hashes prove integrity, not authenticity, biological accuracy or historical paper reproduction.");var text=new StringBuilder("# Native bigWig warnings and required actions\n\n");for(String note:notes)text.append("WARNING: ").append(note).append("\n\n");return text.append(ACTION).append('\n').toString();
    }
    private static long number(BigWigText.Data data,String key)throws IOException {return NextflowFiles.integer(data.audit().get(key),0,Long.MAX_VALUE);}
    private static long total(Map<String,Object> inventory)throws IOException {long sum=0;for(Object value:inventory.values()){var row=NextflowFiles.object(value);if(row.get("kind").equals("file"))sum=Math.addExact(sum,NextflowFiles.fingerprint(row,1099511627776L).bytes());}return sum;}
    private static boolean same(Object a,Object b)throws IOException {return NextflowJson.json(a).equals(NextflowJson.json(b));}
    private static void failure(Path root,String stage,Throwable failure){try{for(String name:new String[]{"COMPLETED.json","manifest.json"})if(Files.exists(root.resolve(name),LinkOption.NOFOLLOW_LINKS))Files.move(root.resolve(name),root.resolve("UNADMITTED-"+name));boolean skip=failure instanceof AccessDeniedException;BigWigFiles.json(root.resolve("FAILURE.json"),Map.of("status",skip?"SKIP3_CONVERSION_SKIPPED":"FAIL2_NO_RESULT_ADMITTED","stage",stage,"error",failure.toString(),"conversion_admitted",false,"required_action",ACTION));Files.writeString(root.resolve("WARNINGS.md"),"\n\n# "+(skip?"SKIP3 — CONVERSION SKIPPED":"FAIL2 — NO RESULT ADMITTED")+"\n\nStage: "+stage+"\n\n"+failure+"\n\n"+ACTION+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE,StandardOpenOption.APPEND);}catch(IOException diagnostic){failure.addSuppressed(diagnostic);}}
    private static void require(boolean condition,String message)throws IOException {BigWigFiles.require(condition,message);}
}
